2	
3	// Section is a `## <Name>` block in WORK.md and its contents.
4	//
5	// Line ranges are JSON-skipped; CLI wire types expose count + the parsed
6	// blocks rather than raw offsets.
7	type Section struct {
8		Name     SectionName `json:"name"`
9		HeadLine int         `json:"-"`
10		EndLine  int         `json:"-"`
11		Blocks   []Block     `json:"blocks"`
12	}
13	
14	// FindBlock returns a pointer to the block with the matching ID (case-
15	// insensitive), or nil if not present.
16	func (s *Section) FindBlock(id string) *Block {
17		for i := range s.Blocks {
18			if equalFoldID(s.Blocks[i].ID, id) {
19				return &s.Blocks[i]
20			}
21		}
22		return nil
23	}
24	
25	func equalFoldID(a, b string) bool {
26		// IDs are lowercase-kebab; the parser already lowercases them, but be
27		// defensive in case a caller passes mixed case.
28		if len(a) != len(b) {
29			return false
30		}
31		for i := 0; i < len(a); i++ {
32			ca, cb := a[i], b[i]
33			if 'A' <= ca && ca <= 'Z' {
34				ca += 'a' - 'A'
35			}
36			if 'A' <= cb && cb <= 'Z' {
37				cb += 'a' - 'A'
38			}
39			if ca != cb {
40				return false
41			}
42		}
43		return true
44	}
