10	// WorkDoc is a parsed WORK.md. After parsing it should be treated as
11	// read-only; the renderer mutates the on-disk file via line splices and
12	// re-parses if it needs an updated model.
13	type WorkDoc struct {
14		Path     string
15		Lines    []string // raw lines, no trailing newline
16		Sections []Section
17	
18		// byID maps lowercase ID → pointer into Sections[i].Blocks[j].
19		// Built by the parser; safe as long as the doc is not mutated post-parse.
20		byID map[string]*Block
21	}
22	
23	// Section returns the section with the given name, or nil.
24	func (d *WorkDoc) Section(name SectionName) *Section {
25		for i := range d.Sections {
26			if d.Sections[i].Name == name {
27				return &d.Sections[i]
28			}
29		}
30		return nil
31	}
32	
33	// BlockByID returns the block with the given ID (case-insensitive), or nil.
34	func (d *WorkDoc) BlockByID(id string) *Block {
35		if d.byID == nil {
36			return nil
37		}
38		return d.byID[strings.ToLower(id)]
39	}
40	
41	// SetByID is used by the parser to install the lookup table. Callers outside
42	// the parser should not invoke it.
43	func (d *WorkDoc) SetByID(m map[string]*Block) { d.byID = m }
