45	// Workdir wraps the worklog data directory.
46	type Workdir struct {
47		Root string
48	}
49	
50	// NewWorkdir resolves root to an absolute path. Empty root → default of
51	// $XDG_DATA_HOME/worklog (or $HOME/.local/share/worklog if XDG isn't set).
52	// "~" prefix is expanded against the user's home directory.
53	func NewWorkdir(root string) (Workdir, error) {
54		if root == "" {
55			if xdg := os.Getenv("XDG_DATA_HOME"); xdg != "" {
56				root = filepath.Join(xdg, "worklog")
57			} else {
58				home, err := os.UserHomeDir()
59				if err != nil {
60					return Workdir{}, err
61				}
62				root = filepath.Join(home, ".local", "share", "worklog")
63			}
64		} else if strings.HasPrefix(root, "~") {
65			home, err := os.UserHomeDir()
66			if err != nil {
67				return Workdir{}, err
68			}
69			root = filepath.Join(home, strings.TrimPrefix(root, "~"))
70		}
71		abs, err := filepath.Abs(root)
72		if err != nil {
73			return Workdir{}, err
74		}
75		return Workdir{Root: abs}, nil
76	}
77	
78	func (w Workdir) WorkMD() string     { return filepath.Join(w.Root, "WORK.md") }
79	func (w Workdir) IndexMD() string    { return filepath.Join(w.Root, "INDEX.md") }
80	func (w Workdir) FeedbackMD() string { return filepath.Join(w.Root, "FEEDBACK.md") }
81	func (w Workdir) NotesDir() string   { return filepath.Join(w.Root, "notes") }
82	func (w Workdir) ArchiveDir() string { return filepath.Join(w.Root, "archive") }
83	
84	// NotesFile returns the canonical path for an epic's notes file.
85	func (w Workdir) NotesFile(id string) string {
86		return filepath.Join(w.NotesDir(), strings.ToLower(id)+".md")
87	}
88	
89	// ArchiveFile returns the canonical path for a given YYYY-MM month.
90	func (w Workdir) ArchiveFile(yyyymm string) string {
91		return filepath.Join(w.ArchiveDir(), yyyymm+".md")
92	}
93	
94	// ErrWorkMDMissing is returned when the worklog data dir has no WORK.md.
95	var ErrWorkMDMissing = errors.New("WORK.md not found")
