1	package cli
2	
3	import (
4		"os"
5		"regexp"
6		"strings"
7	
8		"github.com/prestontallen/ai-devboard/worklog/internal/devboard"
9		"github.com/prestontallen/ai-devboard/worklog/internal/model"
10		"github.com/prestontallen/ai-devboard/worklog/internal/parse"
11	)
12	
13	// syncDevboard runs a devboard side effect and warns on failure. Devboard
14	// mirroring must never fail the primary worklog operation: the ticket
15	// change has already landed by the time these run.
16	func syncDevboard(fn func() error) {
17		if err := fn(); err != nil {
18			logger.Warn("devboard sync failed", "err", err)
19		}
20	}
21	
22	func devboardOnStart(id, title, blockType string) {
23		syncDevboard(func() error { return devboard.OnStart(id, title, blockType) })
24	}
25	func devboardOnDone(id string)    { syncDevboard(func() error { return devboard.OnDone(id) }) }
26	func devboardOnPR(id, url string) { syncDevboard(func() error { return devboard.OnPR(id, url) }) }
27	
28	// devboardOnPRChild mirrors a PR link onto childID's own entry in the
29	// epic's devboard file (via mutateTaskOrChild, same link-replace logic
30	// devboard.OnPR uses for a plain ticket). No-op when the epic has no
31	// devboard file yet — same "no-op when absent" contract as OnPR; nothing
32	// has synced the epic into existence yet, and a bare PR mirror shouldn't
33	// be the thing that does (devboardSyncEpic already owns that, from
34	// start/done).
35	func devboardOnPRChild(epicID, childID, url string) {
36		syncDevboard(func() error {
37			if !devboard.Enabled() {
38				return nil
39			}
40			path, err := devboard.Find(epicID)
41			if err != nil || path == "" {
42				return err
43			}
44			_, err = mutateTaskOrChild(path, childID, func(t *devboard.Task) error {
45				kept := t.Links[:0]
46				for _, l := range t.Links {
47					if l.Label != "PR" {
48						kept = append(kept, l)
49					}
50				}
51				t.Links = kept
52				if url != "" {
53					t.Links = append(t.Links, devboard.Link{Label: "PR", URL: url})
54				}
55				return nil
56			})
57			return err
58		})
59	}
60	
61	// epicChildLineRe matches a notes-file child checkbox line, capturing
62	// state, id, and (unlike the state-only regexes in internal/start and
63	// internal/done) the title — the only place a not-yet-started child's
64	// title lives.
65	var epicChildLineRe = regexp.MustCompile(`^- \[([ ~x])\]\s+([a-zA-Z0-9_-]+)(?::\s*(.*))?$`)
66	
67	// epicRoster reads notes/<epicID>.md's child checkboxes and combines them
68	// with the epic block's WORK.md **Active children**: field to produce the
69	// full three-state roster. A notes checkbox only ever flips to [x] on
70	// archival (never on promotion — see dev-context's "Epic children"
71	// section), so "active" can only be determined from WORK.md, never from
72	// the notes file alone. Missing/empty notes file: returns (nil, nil), not
73	// an error — a child can still start before the epic has any other
74	// history recorded.
75	func epicRoster(wd model.Workdir, epicID string) ([]devboard.ChildIdentity, error) {
76		data, err := os.ReadFile(wd.NotesFile(epicID))
77		if err != nil {
78			if os.IsNotExist(err) {
79				return nil, nil
80			}
81			return nil, err
82		}
83		var active map[string]bool
84		if doc, derr := parse.File(wd.WorkMD()); derr == nil {
85			if blk := doc.BlockByID(epicID); blk != nil {
86				active = make(map[string]bool, len(blk.ActiveChildren))
87				for _, id := range blk.ActiveChildren {
88					active[strings.ToLower(id)] = true
89				}
90			}
91		}
92		var roster []devboard.ChildIdentity
93		for _, line := range strings.Split(string(data), "\n") {
94			m := epicChildLineRe.FindStringSubmatch(line)
95			if m == nil {
96				continue
97			}
98			id := strings.ToLower(m[2])
99			state := devboard.ChildPending
100			switch {
101			case m[1] == "x":
102				state = devboard.ChildDone
103			case active[id]:
104				state = devboard.ChildActive
105			}
106			roster = append(roster, devboard.ChildIdentity{ID: id, Title: strings.TrimSpace(m[3]), State: state})
107		}
108		return roster, nil
109	}
110	
111	// devboardSyncEpic re-syncs an epic's devboard file from the CURRENT
112	// WORK.md + notes state (identity, title, full roster) — called after a
113	// child-of-epic start/resume/done, once WORK.md and notes already reflect
114	// that event, rather than passed incremental deltas. Silent-warn on
115	// failure, same contract as the other devboard* hooks.
116	func devboardSyncEpic(wd model.Workdir, epicID string) {
117		syncDevboard(func() error {
118			if !devboard.Enabled() {
119				return nil
120			}
121			title := ""
122			if doc, err := parse.File(wd.WorkMD()); err == nil {
123				if blk := doc.BlockByID(epicID); blk != nil {
124					title = blk.Title
125				}
126			}
127			roster, err := epicRoster(wd, epicID)
128			if err != nil {
129				return err
130			}
131			return devboard.SyncEpicRoster(epicID, title, roster)
132		})
133	}
