20	// Resolution identifies what kind of ID was passed to start.
21	type Resolution int
22	
23	const (
24		ResUnknown Resolution = iota
25		ResStandalone
26		ResChildOfEpic
27		ResEpic
28		ResAlreadyActive
29	)
