197	// Run is the orchestration entry-point. It parses WORK.md, resolves the id,
198	// applies the appropriate mutation, and writes the result atomically.
199	func Run(wd model.Workdir, in Inputs, today string) (Output, error) {
200		doc, err := parse.File(wd.WorkMD())
201		if err != nil {
202			return Output{}, err
203		}
204	
205		res, err := Resolve(wd, doc, in.ID)
206		if err != nil {
207			return Output{}, err
208		}
209	
210		switch res.Resolution {
211		case ResUnknown:
212			return Output{}, fmt.Errorf("%w: %q", ErrIDNotFound, in.ID)
213		case ResAlreadyActive:
214			return Output{}, fmt.Errorf("%w: %q is already in ## Now", ErrAlreadyStarted, in.ID)
215		case ResEpic:
216			inNow := nowIDSet(doc)
217			var startable []string
218			for _, c := range res.Children {
219				if !inNow[strings.ToLower(c)] {
220					startable = append(startable, c)
221				}
222			}
223			return Output{}, fmt.Errorf("%w; epic %q %s",
224				ErrEpicCannotStart, in.ID, describeChildren(startable, res.Children))
225		}
226	
227		// Cap check. The check only applies when the operation would INCREASE
228		// the count in ## Now (i.e. block isn't already there).
229		nowCount, nowIDs := nowSnapshot(doc)
230		movingFromNow := res.Resolution == ResStandalone &&
231			res.Block.Section == model.SectionNow
232		if !movingFromNow && nowCount >= cap {
233			return Output{}, fmt.Errorf("%w (%d/%d); current Now: %s",
234				ErrCapExceeded, nowCount, cap, strings.Join(nowIDs, ", "))
235		}
236	
237		var (
238			newLines  []string
239			title     string
240			parent    string
241			blockType string
242		)
243	
244		switch res.Resolution {
245		case ResStandalone:
246			title = res.Block.Title
247			parent = res.Block.Parent
248			blockType = string(res.Block.Type)
249			afterRemove, src, err := render.RemoveBlock(doc, in.ID)
250			if err != nil {
251				return Output{}, err
252			}
253			// Re-parse so line numbers are accurate for AppendToSection.
254			afterDoc, err := parse.Bytes(doc.Path, []byte(strings.Join(afterRemove, "\n")))
255			if err != nil {
256				return Output{}, err
257			}
258			blockLines := render.FormatTicketBlock(render.BlockOptions{
259				Title:      src.Title,
260				ID:         src.ID,
261				Type:       string(src.Type),
262				Parent:     src.Parent,
263				Repo:       coalesceStr(in.Repo, src.Repo),
264				Tags:       coalesceTags(in.Tags, src.Tags),
265				Started:    today,
266				PR:         src.PR,
267				Files:      src.Files,
268				Acceptance: coalesceStr(in.Acceptance, src.Acceptance),
269				NotesRef:   src.NotesRef,
270				Status:     src.Status,
271				State:      model.StateActive,
272			})
273			final, err := render.AppendToSection(afterDoc, model.SectionNow, blockLines)
274			if err != nil {
275				return Output{}, err
276			}
277			newLines = final
278	
279		case ResChildOfEpic:
280			// The child came from a notes-file scan; the epic block itself may
281			// be gone (archived epics keep their notes file as history). Refuse
282			// with a clear cause before any mutation.
283			if doc.BlockByID(res.EpicID) == nil {
284				hint := reindex.ArchivedHint(wd.ArchiveDir(), res.EpicID)
285				if hint == "" {
286					hint = "not found and not in the archive"
287				}
288				return Output{}, fmt.Errorf("%w: %q %s; archived epics cannot take new work",
289					ErrParentEpicGone, res.EpicID, hint)
290			}
291			title = res.Block.Title
292			parent = res.EpicID
293			blockLines := render.FormatTicketBlock(render.BlockOptions{
294				Title:      title,
295				ID:         in.ID,
296				Parent:     res.EpicID,
297				Repo:       in.Repo,
298				Tags:       in.Tags,
299				Acceptance: in.Acceptance,
300				Started:    today,
301				State:      model.StateActive,
302			})
303			afterAppend, err := render.AppendToSection(doc, model.SectionNow, blockLines)
304			if err != nil {
305				return Output{}, err
306			}
307			// Re-parse so UpdateEpicActiveChildren sees up-to-date line numbers.
308			afterDoc, err := parse.Bytes(doc.Path, []byte(strings.Join(afterAppend, "\n")))
309			if err != nil {
310				return Output{}, err
311			}
312			final, err := render.UpdateEpicActiveChildren(afterDoc, res.EpicID, in.ID)
313			if err != nil {
314				return Output{}, err
315			}
316			newLines = final
317		}
318	
319		if err := render.WriteAtomic(wd.WorkMD(), newLines); err != nil {
320			return Output{}, err
321		}
322	
323		return Output{
324			Status:   "started",
325			ID:       in.ID,
326			Title:    title,
327			Section:  "Now",
328			Parent:   parent,
329			Type:     blockType,
330			Started:  today,
331			WorkMD:   wd.WorkMD(),
332			Warnings: []string{IndexNotUpdatedWarning},
333		}, nil
334	}
