362	func nowSnapshot(doc *model.WorkDoc) (int, []string) {
363		now := doc.Section(model.SectionNow)
364		if now == nil {
365			return 0, nil
366		}
367		ids := make([]string, 0, len(now.Blocks))
368		for _, b := range now.Blocks {
369			if b.ID != "" {
370				ids = append(ids, b.ID)
371			}
372		}
373		return len(now.Blocks), ids
374	}
